do $pub$
declare
  g constant uuid := '08fc2875-3e69-4e66-b4ac-4e71e1685743';
  es_id constant uuid := 'f674edd8-12ba-4b44-9bd6-8daa78c27330';
  j constant jsonb := $j$[
{"id":"f674edd8-12ba-4b44-9bd6-8daa78c27330","recipe_group_id":"08fc2875-3e69-4e66-b4ac-4e71e1685743","language":"es","slug":"sopa-de-verduras","public_path":"/sopa-de-verduras","source_url":null,"title":"Sopa de verduras","excerpt":"Sopa de verduras casera con caldo claro, papa, zanahoria, calabacín, judías verdes y tomate. Se hace en una olla y rinde 6 porciones.","summary":"Esta sopa de verduras lleva un sofrito de cebolla, ajo, zanahoria y apio, y se cocina en caldo claro con papa, tomate, calabacín y judías verdes. Las verduras quedan en trozos pequeños y tiernos, y el perejil fresco se añade al final.\n\nLleva 20 minutos de preparación y 45 de cocción. Rinde 6 porciones.","category":"Sopas y cremas","difficulty":"Fácil","course":"Sopa","cuisine":"Internacional","prep_time_minutes":20,"cook_time_minutes":45,"total_time_minutes":65,"servings":6,"keywords":["sopa de verduras","receta de sopa de verduras","sopa de verduras casera","cómo hacer sopa de verduras","sopa de verduras con papa","sopa de verduras fácil","sopa de verduras con caldo"],"ingredients":[{"name":"cebolla grande","amount":"1","unit":"","group":"Para el sofrito"},{"name":"dientes de ajo","amount":"3","unit":"","group":"Para el sofrito"},{"name":"zanahorias","amount":"3","unit":"","group":"Para el sofrito"},{"name":"tallos de apio","amount":"2","unit":"","group":"Para el sofrito"},{"name":"aceite de oliva","amount":"2","unit":"cucharada","group":"Para el sofrito"},{"name":"tomates maduros","amount":"3","unit":"","group":"Para la sopa"},{"name":"papas","amount":"2","unit":"","group":"Para la sopa"},{"name":"caldo de verduras","amount":"2000","unit":"ml","group":"Para la sopa"},{"name":"calabacín","amount":"1","unit":"","group":"Para la sopa"},{"name":"judías verdes","amount":"200","unit":"g","group":"Para la sopa"},{"name":"sal","amount":"1","unit":"cucharadita","group":"Para la sopa"},{"name":"pimienta negra","amount":"1/2","unit":"cucharadita","group":"Para la sopa"},{"name":"perejil fresco","amount":"15","unit":"g","group":"Para la sopa"}],"steps":[{"title":"Prepara los ingredientes","content":"Lava bien las verduras y ten a mano 1 cebolla grande, 3 dientes de ajo, 3 zanahorias, 2 tallos de apio, 2 papas, 3 tomates maduros, 1 calabacín, 200 g de judías verdes, perejil, 2 litros de caldo de verduras, aceite de oliva, sal y pimienta.","image_url":"/recetas/sopa-de-verduras/paso-01.webp","image_alt":"Sopa de verduras: Prepara los ingredientes"},{"title":"Corta las verduras","content":"Pica la cebolla y el ajo muy finos. Corta la zanahoria y el apio en cubos de ½ cm, y las papas, el calabacín y los tomates en cubos de 1 cm. Corta las judías verdes en trozos de 1 cm y pica el perejil.","image_url":"/recetas/sopa-de-verduras/paso-02.webp","image_alt":"Sopa de verduras: Corta las verduras"},{"title":"Haz el sofrito","content":"Calienta 2 cucharadas de aceite en una olla grande a fuego medio. Añade la cebolla, el ajo, la zanahoria y el apio con una pizca de sal y cocina 8 minutos, removiendo, hasta que la cebolla esté transparente.","image_url":"/recetas/sopa-de-verduras/paso-03.webp","image_alt":"Sopa de verduras: Haz el sofrito"},{"title":"Añade tomate, papa y caldo","content":"Agrega los tomates y las papas, remueve 2 minutos y vierte los 2 litros de caldo caliente. Sube el fuego hasta que rompa a hervir.","image_url":"/recetas/sopa-de-verduras/paso-04.webp","image_alt":"Sopa de verduras: Añade tomate, papa y caldo"},{"title":"Cocina tapada","content":"Baja a fuego bajo, tapa parcialmente la olla y cocina 15 minutos, hasta que las papas estén casi tiernas.","image_url":"/recetas/sopa-de-verduras/paso-05.webp","image_alt":"Sopa de verduras: Cocina tapada"},{"title":"Añade calabacín y judías","content":"Incorpora el calabacín y las judías verdes. Añade el resto de la cucharadita de sal y la pimienta, y cocina 10 minutos a fuego bajo.","image_url":"/recetas/sopa-de-verduras/paso-06.webp","image_alt":"Sopa de verduras: Añade calabacín y judías"},{"title":"Remueve y comprueba","content":"Remueve con una cuchara de madera y pincha una papa y una judía: deben estar tiernas pero enteras. Si aún están firmes, cocina de 3 a 5 minutos más.","image_url":"/recetas/sopa-de-verduras/paso-07.webp","image_alt":"Sopa de verduras: Remueve y comprueba"},{"title":"Prueba y sirve","content":"Prueba el caldo y ajusta la sal y la pimienta. Apaga el fuego, añade el perejil picado y sirve la sopa bien caliente.","image_url":"/recetas/sopa-de-verduras/paso-08.webp","image_alt":"Sopa de verduras: Prueba y sirve"}],"image_url":"/recetas/sopa-de-verduras/portada.webp","gallery":[{"url":"/recetas/sopa-de-verduras/portada.webp","alt":"Sopa de verduras"}],"notes":"Si usas caldo comprado, pruébalo antes de salar, porque suele traer sal. Corta las verduras de tamaño parecido para que se cocinen al mismo tiempo. El calabacín y las judías se añaden después para que no se deshagan. Se pueden cambiar el calabacín o las judías por otras verduras de temporada, como chícharos o espinacas. La sopa se conserva 4 días en la nevera, bien tapada, y se puede congelar hasta 3 meses; las papas quedan algo más blandas al descongelar.","nutrition":{"calories":166,"protein_g":4.7,"carbs_g":28,"fat_g":5.4,"sodium_mg":643,"serving_size":"1 porción (unos 400 ml)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Suma de nutrientes por 100 g multiplicados por los pesos de los ingredientes y divididos entre 6 porciones: 150 g de cebolla, 9 g de ajo, 240 g de zanahoria, 100 g de apio, 27 g de aceite de oliva, 400 g de tomate, 400 g de papa, 2.000 g de caldo de verduras (aproximado con valores orientativos de caldo casero o bajo en sodio, sin FDC id), 200 g de calabacín, 200 g de judías verdes, 6 g de sal, 1,2 g de pimienta y 15 g de perejil, todo contado.","note":"Estimación por porción. El sodio depende sobre todo del caldo y de la sal que añadas; con caldo comprado puede ser mayor.","inputs":[{"fdc_id":"170000","description":"Onions, raw (1 cebolla grande ≈ 150 g)","grams":150,"per100":{"calories":40,"protein_g":1.1,"carbs_g":9.34,"fat_g":0.1,"saturated_fat_g":0.042,"fiber_g":1.7,"sodium_mg":4}},{"fdc_id":"169230","description":"Garlic, raw (3 dientes ≈ 9 g)","grams":9,"per100":{"calories":149,"protein_g":6.36,"carbs_g":33.06,"fat_g":0.5,"saturated_fat_g":0.089,"fiber_g":2.1,"sodium_mg":17}},{"fdc_id":"170393","description":"Carrots, raw (3 zanahorias medianas ≈ 240 g)","grams":240,"per100":{"calories":41,"protein_g":0.93,"carbs_g":9.58,"fat_g":0.24,"saturated_fat_g":0.037,"fiber_g":2.8,"sodium_mg":69}},{"fdc_id":"169988","description":"Celery, raw (2 tallos ≈ 100 g)","grams":100,"per100":{"calories":14,"protein_g":0.69,"carbs_g":2.97,"fat_g":0.17,"saturated_fat_g":0.042,"fiber_g":1.6,"sodium_mg":80}},{"fdc_id":"171413","description":"Oil, olive, salad or cooking (2 cucharadas ≈ 27 g)","grams":27,"per100":{"calories":884,"protein_g":0,"carbs_g":0,"fat_g":100,"saturated_fat_g":13.8,"fiber_g":0,"sodium_mg":2}},{"fdc_id":"170457","description":"Tomatoes, red, ripe, raw (3 tomates medianos ≈ 400 g)","grams":400,"per100":{"calories":18,"protein_g":0.88,"carbs_g":3.89,"fat_g":0.2,"saturated_fat_g":0.028,"fiber_g":1.2,"sodium_mg":5}},{"fdc_id":"170026","description":"Potatoes, white, flesh and skin, raw (2 papas medianas ≈ 400 g)","grams":400,"per100":{"calories":69,"protein_g":1.68,"carbs_g":15.71,"fat_g":0.1,"saturated_fat_g":0.026,"fiber_g":2.4,"sodium_mg":6}},{"fdc_id":null,"description":"Caldo de verduras casero o bajo en sodio (proxy orientativo; 2 l ≈ 2.000 g)","grams":2000,"per100":{"calories":6,"protein_g":0.3,"carbs_g":1.2,"fat_g":0.1,"saturated_fat_g":0,"fiber_g":0,"sodium_mg":60}},{"fdc_id":"169291","description":"Squash, summer, zucchini, includes skin, raw (1 calabacín ≈ 200 g)","grams":200,"per100":{"calories":17,"protein_g":1.21,"carbs_g":3.11,"fat_g":0.32,"saturated_fat_g":0.084,"fiber_g":1.0,"sodium_mg":8}},{"fdc_id":"169961","description":"Beans, snap, green, raw (200 g)","grams":200,"per100":{"calories":31,"protein_g":1.83,"carbs_g":6.97,"fat_g":0.22,"saturated_fat_g":0.05,"fiber_g":2.7,"sodium_mg":6}},{"fdc_id":"173468","description":"Salt, table (1 cucharadita ≈ 6 g)","grams":6,"per100":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sodium_mg":38758}},{"fdc_id":"170931","description":"Spices, pepper, black (½ cucharadita ≈ 1,2 g)","grams":1.2,"per100":{"calories":251,"protein_g":10.39,"carbs_g":63.95,"fat_g":3.26,"saturated_fat_g":1.392,"fiber_g":25.3,"sodium_mg":20}},{"fdc_id":"170416","description":"Parsley, fresh (15 g)","grams":15,"per100":{"calories":36,"protein_g":2.97,"carbs_g":6.33,"fat_g":0.79,"saturated_fat_g":0.132,"fiber_g":3.3,"sodium_mg":56}}]},"seo":{"title":"Sopa de verduras casera con papa y judías verdes | Manual de Cocina","description":"Sopa de verduras casera con caldo claro, papa, zanahoria, calabacín, judías verdes y tomate. Se hace en una olla y rinde 6 porciones. Paso a paso con fotos.","image_variants":["/recetas/sopa-de-verduras/portada-1x1.webp","/recetas/sopa-de-verduras/portada-4x3.webp","/recetas/sopa-de-verduras/portada-16x9.webp"],"faq":[{"q":"¿Cuánto tiempo se cocina la sopa de verduras?","a":"Unos 45 minutos en total: 8 de sofrito, 15 hasta que las papas estén casi tiernas y 10 más con el calabacín y las judías."},{"q":"¿Se puede congelar la sopa de verduras?","a":"Sí, hasta 3 meses en recipientes cerrados. Al descongelarla, las papas quedan algo más blandas, pero el sabor se mantiene."},{"q":"¿Qué verduras puedo cambiar en la sopa?","a":"Puedes cambiar el calabacín o las judías por chícharos, espinacas, repollo o batata. Añade las verduras más duras primero y las más tiernas al final."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"8a0ff0c6-aa01-5540-941d-12c474e02c66","recipe_group_id":"08fc2875-3e69-4e66-b4ac-4e71e1685743","language":"de","slug":"gemuesesuppe","public_path":"/de/gemuesesuppe","source_url":null,"title":"Gemüsesuppe mit Kartoffeln und grünen Bohnen","excerpt":"Hausgemachte Gemüsesuppe mit klarer Brühe, Kartoffeln, Karotten, Zucchini, grünen Bohnen und Tomaten. In einem Topf gekocht, 6 Portionen.","summary":"Diese Gemüsesuppe beginnt mit einem Soffritto aus Zwiebel, Knoblauch, Karotte und Staudensellerie und gart in klarer Brühe mit Kartoffeln, Tomaten, Zucchini und grünen Bohnen. Das Gemüse bleibt in kleinen, zarten Stücken, und frische Petersilie kommt zum Schluss dazu.\n\nSie braucht 20 Minuten Vorbereitung und 45 Minuten Kochzeit. Ergibt 6 Portionen.","category":"Suppen und Cremesuppen","difficulty":"Einfach","course":"Suppe","cuisine":"International","prep_time_minutes":20,"cook_time_minutes":45,"total_time_minutes":65,"servings":6,"keywords":["Gemüsesuppe","Gemüsesuppe Rezept","Gemüsesuppe selber machen","Gemüsesuppe mit Kartoffeln","Gemüsesuppe mit grünen Bohnen","einfache Gemüsesuppe","Gemüsesuppe mit klarer Brühe"],"ingredients":[{"name":"große Zwiebel","amount":"1","unit":"","group":"Für den Soffritto"},{"name":"Knoblauchzehen","amount":"3","unit":"","group":"Für den Soffritto"},{"name":"Karotten","amount":"3","unit":"","group":"Für den Soffritto"},{"name":"Stangen Staudensellerie","amount":"2","unit":"","group":"Für den Soffritto"},{"name":"Olivenöl","amount":"2","unit":"Esslöffel","group":"Für den Soffritto"},{"name":"reife Tomaten","amount":"3","unit":"","group":"Für die Suppe"},{"name":"Kartoffeln","amount":"2","unit":"","group":"Für die Suppe"},{"name":"Gemüsebrühe","amount":"2000","unit":"ml","group":"Für die Suppe"},{"name":"Zucchini","amount":"1","unit":"","group":"Für die Suppe"},{"name":"grüne Bohnen","amount":"200","unit":"g","group":"Für die Suppe"},{"name":"Salz","amount":"1","unit":"Teelöffel","group":"Für die Suppe"},{"name":"schwarzer Pfeffer","amount":"1/2","unit":"Teelöffel","group":"Für die Suppe"},{"name":"frische Petersilie","amount":"15","unit":"g","group":"Für die Suppe"}],"steps":[{"title":"Zutaten vorbereiten","content":"Das Gemüse gründlich waschen und 1 große Zwiebel, 3 Knoblauchzehen, 3 Karotten, 2 Stangen Staudensellerie, 2 Kartoffeln, 3 reife Tomaten, 1 Zucchini, 200 g grüne Bohnen, Petersilie, 2 Liter Gemüsebrühe, Olivenöl, Salz und Pfeffer bereitstellen.","image_url":"/recetas/sopa-de-verduras/paso-01.webp","image_alt":"Gemüsesuppe mit Kartoffeln und grünen Bohnen: Zutaten vorbereiten"},{"title":"Gemüse schneiden","content":"Zwiebel und Knoblauch sehr fein hacken. Karotte und Sellerie in ½-cm-Würfel, Kartoffeln, Zucchini und Tomaten in 1-cm-Würfel schneiden. Die grünen Bohnen in 1-cm-Stücke schneiden und die Petersilie hacken.","image_url":"/recetas/sopa-de-verduras/paso-02.webp","image_alt":"Gemüsesuppe mit Kartoffeln und grünen Bohnen: Gemüse schneiden"},{"title":"Soffritto ansetzen","content":"2 Esslöffel Öl in einem großen Topf bei mittlerer Hitze erhitzen. Zwiebel, Knoblauch, Karotte und Sellerie mit einer Prise Salz dazugeben und 8 Minuten unter Rühren garen, bis die Zwiebel glasig ist.","image_url":"/recetas/sopa-de-verduras/paso-03.webp","image_alt":"Gemüsesuppe mit Kartoffeln und grünen Bohnen: Soffritto ansetzen"},{"title":"Tomaten, Kartoffeln und Brühe zugeben","content":"Tomaten und Kartoffeln hinzufügen, 2 Minuten rühren und die 2 Liter heiße Brühe angießen. Die Hitze erhöhen, bis es aufkocht.","image_url":"/recetas/sopa-de-verduras/paso-04.webp","image_alt":"Gemüsesuppe mit Kartoffeln und grünen Bohnen: Tomaten, Kartoffeln und Brühe zugeben"},{"title":"Zugedeckt garen","content":"Die Hitze auf niedrig stellen, den Topf halb zudecken und 15 Minuten garen, bis die Kartoffeln fast weich sind.","image_url":"/recetas/sopa-de-verduras/paso-05.webp","image_alt":"Gemüsesuppe mit Kartoffeln und grünen Bohnen: Zugedeckt garen"},{"title":"Zucchini und Bohnen zugeben","content":"Zucchini und grüne Bohnen hinzufügen. Das restliche Salz des Teelöffels und den Pfeffer dazugeben und 10 Minuten bei niedriger Hitze garen.","image_url":"/recetas/sopa-de-verduras/paso-06.webp","image_alt":"Gemüsesuppe mit Kartoffeln und grünen Bohnen: Zucchini und Bohnen zugeben"},{"title":"Umrühren und prüfen","content":"Mit einem Holzlöffel umrühren und eine Kartoffel und eine Bohne anstechen: Sie sollen weich, aber noch ganz sein. Sind sie noch fest, 3 bis 5 Minuten weitergaren.","image_url":"/recetas/sopa-de-verduras/paso-07.webp","image_alt":"Gemüsesuppe mit Kartoffeln und grünen Bohnen: Umrühren und prüfen"},{"title":"Abschmecken und servieren","content":"Die Brühe probieren und Salz und Pfeffer anpassen. Den Herd ausschalten, die gehackte Petersilie unterrühren und die Suppe heiß servieren.","image_url":"/recetas/sopa-de-verduras/paso-08.webp","image_alt":"Gemüsesuppe mit Kartoffeln und grünen Bohnen: Abschmecken und servieren"}],"image_url":"/recetas/sopa-de-verduras/portada.webp","gallery":[{"url":"/recetas/sopa-de-verduras/portada.webp","alt":"Gemüsesuppe mit Kartoffeln und grünen Bohnen"}],"notes":"Bei gekaufter Brühe zuerst probieren, bevor Sie salzen, denn sie enthält meist schon Salz. Das Gemüse in ähnlich große Stücke schneiden, damit alles gleichzeitig gar wird. Zucchini und Bohnen kommen später hinein, damit sie nicht zerfallen. Zucchini oder Bohnen lassen sich durch Gemüse der Saison ersetzen, etwa Erbsen oder Spinat. Die Suppe hält sich gut abgedeckt 4 Tage im Kühlschrank und lässt sich bis zu 3 Monate einfrieren; die Kartoffeln werden nach dem Auftauen etwas weicher.","nutrition":{"calories":166,"protein_g":4.7,"carbs_g":28,"fat_g":5.4,"sodium_mg":643,"serving_size":"1 Portion (etwa 400 ml)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nährwerte je 100 g, multipliziert mit dem Gewicht der Zutaten und durch 6 Portionen geteilt: 150 g Zwiebel, 9 g Knoblauch, 240 g Karotte, 100 g Staudensellerie, 27 g Olivenöl, 400 g Tomate, 400 g Kartoffel, 2.000 g Gemüsebrühe (mit Richtwerten für selbstgemachte oder salzarme Brühe angenähert, ohne FDC-ID), 200 g Zucchini, 200 g grüne Bohnen, 6 g Salz, 1,2 g Pfeffer und 15 g Petersilie, alles gezählt.","note":"Schätzung pro Portion. Der Natriumgehalt hängt vor allem von der Brühe und dem zugegebenen Salz ab; bei gekaufter Brühe kann er höher sein."},"seo":{"title":"Gemüsesuppe mit Kartoffeln und grünen Bohnen | Manual de Cocina","description":"Hausgemachte Gemüsesuppe mit klarer Brühe, Kartoffeln, Karotten, Zucchini, grünen Bohnen und Tomaten. In einem Topf, 6 Portionen. Schritt für Schritt mit Fotos.","image_variants":["/recetas/sopa-de-verduras/portada-1x1.webp","/recetas/sopa-de-verduras/portada-4x3.webp","/recetas/sopa-de-verduras/portada-16x9.webp"],"faq":[{"q":"Wie lange kocht die Gemüsesuppe?","a":"Insgesamt etwa 45 Minuten: 8 für den Soffritto, 15, bis die Kartoffeln fast weich sind, und 10 weitere mit Zucchini und Bohnen."},{"q":"Kann man Gemüsesuppe einfrieren?","a":"Ja, bis zu 3 Monate in verschlossenen Behältern. Nach dem Auftauen werden die Kartoffeln etwas weicher, der Geschmack bleibt erhalten."},{"q":"Welches Gemüse kann ich austauschen?","a":"Zucchini oder Bohnen lassen sich durch Erbsen, Spinat, Weißkohl oder Süßkartoffel ersetzen. Festeres Gemüse zuerst, zarteres zum Schluss hinzufügen."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"c98d6487-4453-52a8-80ab-a4396b728366","recipe_group_id":"08fc2875-3e69-4e66-b4ac-4e71e1685743","language":"en","slug":"vegetable-soup","public_path":"/en/vegetable-soup","source_url":null,"title":"Vegetable Soup with Potatoes and Green Beans","excerpt":"Homemade vegetable soup with a clear broth, potatoes, carrots, zucchini, green beans and tomatoes. Made in one pot, serves 6.","summary":"This vegetable soup starts with a sofrito of onion, garlic, carrot and celery, then simmers in a clear broth with potatoes, tomatoes, zucchini and green beans. The vegetables stay in small, tender pieces, and fresh parsley goes in at the end.\n\nIt takes 20 minutes of prep and 45 of cooking. It serves 6.","category":"Soups & creams","difficulty":"Easy","course":"Soup","cuisine":"International","prep_time_minutes":20,"cook_time_minutes":45,"total_time_minutes":65,"servings":6,"keywords":["vegetable soup","vegetable soup recipe","homemade vegetable soup","how to make vegetable soup","vegetable soup with potatoes","easy vegetable soup","clear vegetable soup"],"ingredients":[{"name":"large onion","amount":"1","unit":"","group":"For the sofrito"},{"name":"garlic cloves","amount":"3","unit":"","group":"For the sofrito"},{"name":"carrots","amount":"3","unit":"","group":"For the sofrito"},{"name":"celery stalks","amount":"2","unit":"","group":"For the sofrito"},{"name":"olive oil","amount":"2","unit":"tablespoon","group":"For the sofrito"},{"name":"ripe tomatoes","amount":"3","unit":"","group":"For the soup"},{"name":"potatoes","amount":"2","unit":"","group":"For the soup"},{"name":"vegetable broth","amount":"2000","unit":"ml","group":"For the soup"},{"name":"zucchini","amount":"1","unit":"","group":"For the soup"},{"name":"green beans","amount":"200","unit":"g","group":"For the soup"},{"name":"salt","amount":"1","unit":"teaspoon","group":"For the soup"},{"name":"black pepper","amount":"1/2","unit":"teaspoon","group":"For the soup"},{"name":"fresh parsley","amount":"15","unit":"g","group":"For the soup"}],"steps":[{"title":"Prepare the ingredients","content":"Wash the vegetables well and have ready 1 large onion, 3 garlic cloves, 3 carrots, 2 celery stalks, 2 potatoes, 3 ripe tomatoes, 1 zucchini, 200 g green beans, parsley, 2 liters of vegetable broth, olive oil, salt and pepper.","image_url":"/recetas/sopa-de-verduras/paso-01.webp","image_alt":"Vegetable Soup with Potatoes and Green Beans: Prepare the ingredients"},{"title":"Chop the vegetables","content":"Mince the onion and garlic finely. Cut the carrot and celery into ½ cm cubes, and the potatoes, zucchini and tomatoes into 1 cm cubes. Cut the green beans into 1 cm pieces and chop the parsley.","image_url":"/recetas/sopa-de-verduras/paso-02.webp","image_alt":"Vegetable Soup with Potatoes and Green Beans: Chop the vegetables"},{"title":"Make the sofrito","content":"Heat 2 tablespoons of oil in a large pot over medium heat. Add the onion, garlic, carrot and celery with a pinch of salt and cook for 8 minutes, stirring, until the onion is translucent.","image_url":"/recetas/sopa-de-verduras/paso-03.webp","image_alt":"Vegetable Soup with Potatoes and Green Beans: Make the sofrito"},{"title":"Add tomatoes, potatoes and broth","content":"Add the tomatoes and potatoes, stir for 2 minutes and pour in the 2 liters of hot broth. Raise the heat until it comes to a boil.","image_url":"/recetas/sopa-de-verduras/paso-04.webp","image_alt":"Vegetable Soup with Potatoes and Green Beans: Add tomatoes, potatoes and broth"},{"title":"Simmer covered","content":"Lower to low heat, partially cover the pot and cook for 15 minutes, until the potatoes are almost tender.","image_url":"/recetas/sopa-de-verduras/paso-05.webp","image_alt":"Vegetable Soup with Potatoes and Green Beans: Simmer covered"},{"title":"Add zucchini and green beans","content":"Add the zucchini and green beans. Add the rest of the teaspoon of salt and the pepper, and cook for 10 minutes over low heat.","image_url":"/recetas/sopa-de-verduras/paso-06.webp","image_alt":"Vegetable Soup with Potatoes and Green Beans: Add zucchini and green beans"},{"title":"Stir and check","content":"Stir with a wooden spoon and pierce a potato and a bean: they should be tender but whole. If they are still firm, cook for 3 to 5 more minutes.","image_url":"/recetas/sopa-de-verduras/paso-07.webp","image_alt":"Vegetable Soup with Potatoes and Green Beans: Stir and check"},{"title":"Taste and serve","content":"Taste the broth and adjust the salt and pepper. Turn off the heat, stir in the chopped parsley and serve the soup piping hot.","image_url":"/recetas/sopa-de-verduras/paso-08.webp","image_alt":"Vegetable Soup with Potatoes and Green Beans: Taste and serve"}],"image_url":"/recetas/sopa-de-verduras/portada.webp","gallery":[{"url":"/recetas/sopa-de-verduras/portada.webp","alt":"Vegetable Soup with Potatoes and Green Beans"}],"notes":"If you use store-bought broth, taste it before salting, because it is usually already salted. Cut the vegetables to a similar size so they cook at the same time. The zucchini and green beans go in later so they do not fall apart. You can swap the zucchini or green beans for other seasonal vegetables, such as peas or spinach. The soup keeps for 4 days in the fridge, well covered, and can be frozen for up to 3 months; the potatoes are a little softer after thawing.","nutrition":{"calories":166,"protein_g":4.7,"carbs_g":28,"fat_g":5.4,"sodium_mg":643,"serving_size":"1 serving (about 400 ml)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nutrients per 100 g multiplied by the weights of the ingredients and divided by 6 servings: 150 g onion, 9 g garlic, 240 g carrot, 100 g celery, 27 g olive oil, 400 g tomato, 400 g potato, 2,000 g vegetable broth (approximated with indicative values for homemade or low-sodium broth, with no FDC id), 200 g zucchini, 200 g green beans, 6 g salt, 1.2 g pepper and 15 g parsley, all counted.","note":"Estimate per serving. Sodium depends mostly on the broth and the salt you add; with store-bought broth it can be higher."},"seo":{"title":"Vegetable Soup with Potatoes and Green Beans | Manual de Cocina","description":"Homemade vegetable soup with a clear broth, potatoes, carrots, zucchini, green beans and tomatoes. One pot, serves 6. Step by step with photos.","image_variants":["/recetas/sopa-de-verduras/portada-1x1.webp","/recetas/sopa-de-verduras/portada-4x3.webp","/recetas/sopa-de-verduras/portada-16x9.webp"],"faq":[{"q":"How long does vegetable soup take to cook?","a":"About 45 minutes in total: 8 for the sofrito, 15 until the potatoes are almost tender, and 10 more with the zucchini and green beans."},{"q":"Can you freeze vegetable soup?","a":"Yes, for up to 3 months in closed containers. After thawing, the potatoes are a little softer, but the flavor holds."},{"q":"Which vegetables can I swap in the soup?","a":"You can swap the zucchini or green beans for peas, spinach, cabbage or sweet potato. Add the firmer vegetables first and the more tender ones at the end."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"3c223cca-7234-5a22-85b5-d99e88b97999","recipe_group_id":"08fc2875-3e69-4e66-b4ac-4e71e1685743","language":"fr","slug":"soupe-de-legumes","public_path":"/fr/soupe-de-legumes","source_url":null,"title":"Soupe de légumes aux pommes de terre et haricots verts","excerpt":"Soupe de légumes maison au bouillon clair, avec pommes de terre, carottes, courgette, haricots verts et tomates. Préparée dans une seule casserole, pour 6 portions.","summary":"Cette soupe de légumes commence par un sofrito d'oignon, d'ail, de carotte et de céleri branche, puis mijote dans un bouillon clair avec des pommes de terre, des tomates, de la courgette et des haricots verts. Les légumes restent en petits morceaux tendres, et le persil frais est ajouté à la fin.\n\nElle demande 20 minutes de préparation et 45 de cuisson. Pour 6 portions.","category":"Soupes et crèmes","difficulty":"Facile","course":"Soupe","cuisine":"Internationale","prep_time_minutes":20,"cook_time_minutes":45,"total_time_minutes":65,"servings":6,"keywords":["soupe de légumes","recette de soupe de légumes","soupe de légumes maison","comment faire une soupe de légumes","soupe de légumes aux pommes de terre","soupe de légumes facile","soupe de légumes au bouillon clair"],"ingredients":[{"name":"gros oignon","amount":"1","unit":"","group":"Pour le sofrito"},{"name":"gousses d'ail","amount":"3","unit":"","group":"Pour le sofrito"},{"name":"carottes","amount":"3","unit":"","group":"Pour le sofrito"},{"name":"branches de céleri","amount":"2","unit":"","group":"Pour le sofrito"},{"name":"huile d'olive","amount":"2","unit":"cuillère à soupe","group":"Pour le sofrito"},{"name":"tomates mûres","amount":"3","unit":"","group":"Pour la soupe"},{"name":"pommes de terre","amount":"2","unit":"","group":"Pour la soupe"},{"name":"bouillon de légumes","amount":"2000","unit":"ml","group":"Pour la soupe"},{"name":"courgette","amount":"1","unit":"","group":"Pour la soupe"},{"name":"haricots verts","amount":"200","unit":"g","group":"Pour la soupe"},{"name":"sel","amount":"1","unit":"cuillère à café","group":"Pour la soupe"},{"name":"poivre noir","amount":"1/2","unit":"cuillère à café","group":"Pour la soupe"},{"name":"persil frais","amount":"15","unit":"g","group":"Pour la soupe"}],"steps":[{"title":"Préparer les ingrédients","content":"Bien laver les légumes et prévoir 1 gros oignon, 3 gousses d'ail, 3 carottes, 2 branches de céleri, 2 pommes de terre, 3 tomates mûres, 1 courgette, 200 g de haricots verts, du persil, 2 litres de bouillon de légumes, de l'huile d'olive, du sel et du poivre.","image_url":"/recetas/sopa-de-verduras/paso-01.webp","image_alt":"Soupe de légumes aux pommes de terre et haricots verts: Préparer les ingrédients"},{"title":"Couper les légumes","content":"Hacher très finement l'oignon et l'ail. Couper la carotte et le céleri en dés de ½ cm, et les pommes de terre, la courgette et les tomates en dés de 1 cm. Couper les haricots verts en morceaux de 1 cm et hacher le persil.","image_url":"/recetas/sopa-de-verduras/paso-02.webp","image_alt":"Soupe de légumes aux pommes de terre et haricots verts: Couper les légumes"},{"title":"Préparer le sofrito","content":"Chauffer 2 cuillères à soupe d'huile dans une grande casserole à feu moyen. Ajouter l'oignon, l'ail, la carotte et le céleri avec une pincée de sel et cuire 8 minutes en remuant, jusqu'à ce que l'oignon soit translucide.","image_url":"/recetas/sopa-de-verduras/paso-03.webp","image_alt":"Soupe de légumes aux pommes de terre et haricots verts: Préparer le sofrito"},{"title":"Ajouter tomates, pommes de terre et bouillon","content":"Ajouter les tomates et les pommes de terre, remuer 2 minutes et verser les 2 litres de bouillon chaud. Monter le feu jusqu'à ébullition.","image_url":"/recetas/sopa-de-verduras/paso-04.webp","image_alt":"Soupe de légumes aux pommes de terre et haricots verts: Ajouter tomates, pommes de terre et bouillon"},{"title":"Cuire à couvert","content":"Baisser à feu doux, couvrir à moitié la casserole et cuire 15 minutes, jusqu'à ce que les pommes de terre soient presque tendres.","image_url":"/recetas/sopa-de-verduras/paso-05.webp","image_alt":"Soupe de légumes aux pommes de terre et haricots verts: Cuire à couvert"},{"title":"Ajouter courgette et haricots verts","content":"Incorporer la courgette et les haricots verts. Ajouter le reste de la cuillère à café de sel et le poivre, et cuire 10 minutes à feu doux.","image_url":"/recetas/sopa-de-verduras/paso-06.webp","image_alt":"Soupe de légumes aux pommes de terre et haricots verts: Ajouter courgette et haricots verts"},{"title":"Remuer et vérifier","content":"Remuer avec une cuillère en bois et piquer une pomme de terre et un haricot : ils doivent être tendres mais entiers. S'ils sont encore fermes, cuire 3 à 5 minutes de plus.","image_url":"/recetas/sopa-de-verduras/paso-07.webp","image_alt":"Soupe de légumes aux pommes de terre et haricots verts: Remuer et vérifier"},{"title":"Goûter et servir","content":"Goûter le bouillon et rectifier le sel et le poivre. Éteindre le feu, ajouter le persil haché et servir la soupe bien chaude.","image_url":"/recetas/sopa-de-verduras/paso-08.webp","image_alt":"Soupe de légumes aux pommes de terre et haricots verts: Goûter et servir"}],"image_url":"/recetas/sopa-de-verduras/portada.webp","gallery":[{"url":"/recetas/sopa-de-verduras/portada.webp","alt":"Soupe de légumes aux pommes de terre et haricots verts"}],"notes":"Si vous utilisez du bouillon du commerce, goûtez-le avant de saler, car il est souvent déjà salé. Coupez les légumes en morceaux de taille proche pour qu'ils cuisent en même temps. La courgette et les haricots verts sont ajoutés plus tard pour ne pas se défaire. On peut remplacer la courgette ou les haricots verts par d'autres légumes de saison, comme des petits pois ou des épinards. La soupe se conserve 4 jours au réfrigérateur, bien couverte, et peut être congelée jusqu'à 3 mois ; les pommes de terre sont un peu plus molles après décongélation.","nutrition":{"calories":166,"protein_g":4.7,"carbs_g":28,"fat_g":5.4,"sodium_mg":643,"serving_size":"1 portion (environ 400 ml)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Somme des nutriments pour 100 g multipliés par le poids des ingrédients et divisés par 6 portions : 150 g d'oignon, 9 g d'ail, 240 g de carotte, 100 g de céleri, 27 g d'huile d'olive, 400 g de tomate, 400 g de pomme de terre, 2 000 g de bouillon de légumes (approché avec des valeurs indicatives de bouillon maison ou pauvre en sodium, sans identifiant FDC), 200 g de courgette, 200 g de haricots verts, 6 g de sel, 1,2 g de poivre et 15 g de persil, le tout compté.","note":"Estimation par portion. Le sodium dépend surtout du bouillon et du sel ajouté ; avec un bouillon du commerce, il peut être plus élevé."},"seo":{"title":"Soupe de légumes aux pommes de terre et haricots verts | Manual de Cocina","description":"Soupe de légumes maison au bouillon clair, avec pommes de terre, carottes, courgette, haricots verts et tomates. Une seule casserole, 6 portions. En photos.","image_variants":["/recetas/sopa-de-verduras/portada-1x1.webp","/recetas/sopa-de-verduras/portada-4x3.webp","/recetas/sopa-de-verduras/portada-16x9.webp"],"faq":[{"q":"Combien de temps cuit la soupe de légumes ?","a":"Environ 45 minutes au total : 8 pour le sofrito, 15 jusqu'à ce que les pommes de terre soient presque tendres et 10 de plus avec la courgette et les haricots verts."},{"q":"Peut-on congeler la soupe de légumes ?","a":"Oui, jusqu'à 3 mois dans des récipients fermés. Après décongélation, les pommes de terre sont un peu plus molles, mais le goût reste bon."},{"q":"Quels légumes puis-je remplacer dans la soupe ?","a":"Vous pouvez remplacer la courgette ou les haricots verts par des petits pois, des épinards, du chou ou de la patate douce. Ajoutez d'abord les légumes les plus fermes et les plus tendres à la fin."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"35471450-d833-5fdb-9c2e-1fdd5895b575","recipe_group_id":"08fc2875-3e69-4e66-b4ac-4e71e1685743","language":"it","slug":"minestra-di-verdure","public_path":"/it/minestra-di-verdure","source_url":null,"title":"Minestra di verdure con patate e fagiolini","excerpt":"Minestra di verdure fatta in casa con brodo chiaro, patate, carote, zucchina, fagiolini e pomodori. Si prepara in una sola pentola, per 6 porzioni.","summary":"Questa minestra di verdure inizia con un soffritto di cipolla, aglio, carota e sedano, e cuoce in un brodo chiaro con patate, pomodori, zucchina e fagiolini. Le verdure restano in pezzetti piccoli e teneri, e il prezzemolo fresco si aggiunge alla fine.\n\nRichiede 20 minuti di preparazione e 45 di cottura. Per 6 porzioni.","category":"Zuppe e creme","difficulty":"Facile","course":"Primo piatto","cuisine":"Internazionale","prep_time_minutes":20,"cook_time_minutes":45,"total_time_minutes":65,"servings":6,"keywords":["minestra di verdure","ricetta minestra di verdure","minestra di verdure fatta in casa","come fare la minestra di verdure","minestra di verdure con patate","minestra di verdure facile","minestra di verdure con brodo"],"ingredients":[{"name":"cipolla grande","amount":"1","unit":"","group":"Per il soffritto"},{"name":"spicchi d'aglio","amount":"3","unit":"","group":"Per il soffritto"},{"name":"carote","amount":"3","unit":"","group":"Per il soffritto"},{"name":"coste di sedano","amount":"2","unit":"","group":"Per il soffritto"},{"name":"olio d'oliva","amount":"2","unit":"cucchiaio","group":"Per il soffritto"},{"name":"pomodori maturi","amount":"3","unit":"","group":"Per la minestra"},{"name":"patate","amount":"2","unit":"","group":"Per la minestra"},{"name":"brodo vegetale","amount":"2000","unit":"ml","group":"Per la minestra"},{"name":"zucchina","amount":"1","unit":"","group":"Per la minestra"},{"name":"fagiolini","amount":"200","unit":"g","group":"Per la minestra"},{"name":"sale","amount":"1","unit":"cucchiaino","group":"Per la minestra"},{"name":"pepe nero","amount":"1/2","unit":"cucchiaino","group":"Per la minestra"},{"name":"prezzemolo fresco","amount":"15","unit":"g","group":"Per la minestra"}],"steps":[{"title":"Prepara gli ingredienti","content":"Lava bene le verdure e tieni pronti 1 cipolla grande, 3 spicchi d'aglio, 3 carote, 2 coste di sedano, 2 patate, 3 pomodori maturi, 1 zucchina, 200 g di fagiolini, prezzemolo, 2 litri di brodo vegetale, olio d'oliva, sale e pepe.","image_url":"/recetas/sopa-de-verduras/paso-01.webp","image_alt":"Minestra di verdure con patate e fagiolini: Prepara gli ingredienti"},{"title":"Taglia le verdure","content":"Trita finemente la cipolla e l'aglio. Taglia la carota e il sedano a cubetti di ½ cm, e le patate, la zucchina e i pomodori a cubetti di 1 cm. Taglia i fagiolini a pezzi di 1 cm e trita il prezzemolo.","image_url":"/recetas/sopa-de-verduras/paso-02.webp","image_alt":"Minestra di verdure con patate e fagiolini: Taglia le verdure"},{"title":"Prepara il soffritto","content":"Scalda 2 cucchiai di olio in una pentola grande a fuoco medio. Aggiungi la cipolla, l'aglio, la carota e il sedano con un pizzico di sale e cuoci 8 minuti, mescolando, finché la cipolla è traslucida.","image_url":"/recetas/sopa-de-verduras/paso-03.webp","image_alt":"Minestra di verdure con patate e fagiolini: Prepara il soffritto"},{"title":"Aggiungi pomodori, patate e brodo","content":"Unisci i pomodori e le patate, mescola 2 minuti e versa i 2 litri di brodo caldo. Alza la fiamma fino a bollore.","image_url":"/recetas/sopa-de-verduras/paso-04.webp","image_alt":"Minestra di verdure con patate e fagiolini: Aggiungi pomodori, patate e brodo"},{"title":"Cuoci con il coperchio","content":"Abbassa la fiamma, copri la pentola a metà e cuoci 15 minuti, finché le patate sono quasi tenere.","image_url":"/recetas/sopa-de-verduras/paso-05.webp","image_alt":"Minestra di verdure con patate e fagiolini: Cuoci con il coperchio"},{"title":"Aggiungi zucchina e fagiolini","content":"Unisci la zucchina e i fagiolini. Aggiungi il resto del cucchiaino di sale e il pepe e cuoci 10 minuti a fiamma bassa.","image_url":"/recetas/sopa-de-verduras/paso-06.webp","image_alt":"Minestra di verdure con patate e fagiolini: Aggiungi zucchina e fagiolini"},{"title":"Mescola e controlla","content":"Mescola con un cucchiaio di legno e infilza una patata e un fagiolino: devono essere teneri ma interi. Se sono ancora sodi, cuoci altri 3-5 minuti.","image_url":"/recetas/sopa-de-verduras/paso-07.webp","image_alt":"Minestra di verdure con patate e fagiolini: Mescola e controlla"},{"title":"Assaggia e servi","content":"Assaggia il brodo e regola sale e pepe. Spegni il fuoco, aggiungi il prezzemolo tritato e servi la minestra ben calda.","image_url":"/recetas/sopa-de-verduras/paso-08.webp","image_alt":"Minestra di verdure con patate e fagiolini: Assaggia e servi"}],"image_url":"/recetas/sopa-de-verduras/portada.webp","gallery":[{"url":"/recetas/sopa-de-verduras/portada.webp","alt":"Minestra di verdure con patate e fagiolini"}],"notes":"Se usi un brodo già pronto, assaggialo prima di salare, perché di solito è già salato. Taglia le verdure di dimensioni simili perché cuociano insieme. La zucchina e i fagiolini si aggiungono dopo perché non si disfino. Puoi sostituire la zucchina o i fagiolini con altre verdure di stagione, come piselli o spinaci. La minestra si conserva 4 giorni in frigorifero, ben coperta, e si può congelare fino a 3 mesi; le patate risultano un po' più morbide dopo lo scongelamento.","nutrition":{"calories":166,"protein_g":4.7,"carbs_g":28,"fat_g":5.4,"sodium_mg":643,"serving_size":"1 porzione (circa 400 ml)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Somma dei nutrienti per 100 g moltiplicati per i pesi degli ingredienti e divisi per 6 porzioni: 150 g di cipolla, 9 g di aglio, 240 g di carota, 100 g di sedano, 27 g di olio d'oliva, 400 g di pomodoro, 400 g di patata, 2.000 g di brodo vegetale (approssimato con valori indicativi di brodo fatto in casa o povero di sodio, senza id FDC), 200 g di zucchina, 200 g di fagiolini, 6 g di sale, 1,2 g di pepe e 15 g di prezzemolo, tutto contato.","note":"Stima per porzione. Il sodio dipende soprattutto dal brodo e dal sale aggiunto; con un brodo già pronto può essere più alto."},"seo":{"title":"Minestra di verdure con patate e fagiolini | Manual de Cocina","description":"Minestra di verdure fatta in casa con brodo chiaro, patate, carote, zucchina, fagiolini e pomodori. Una sola pentola, 6 porzioni. Passo dopo passo con foto.","image_variants":["/recetas/sopa-de-verduras/portada-1x1.webp","/recetas/sopa-de-verduras/portada-4x3.webp","/recetas/sopa-de-verduras/portada-16x9.webp"],"faq":[{"q":"Quanto tempo cuoce la minestra di verdure?","a":"Circa 45 minuti in tutto: 8 per il soffritto, 15 finché le patate sono quasi tenere e altri 10 con la zucchina e i fagiolini."},{"q":"Si può congelare la minestra di verdure?","a":"Sì, fino a 3 mesi in contenitori chiusi. Dopo lo scongelamento le patate sono un po' più morbide, ma il sapore resta."},{"q":"Quali verdure posso sostituire nella minestra?","a":"Puoi sostituire la zucchina o i fagiolini con piselli, spinaci, cavolo o patata dolce. Aggiungi prima le verdure più sode e alla fine quelle più tenere."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"e61b30fd-0581-5d36-bdb5-6fc16496ad98","recipe_group_id":"08fc2875-3e69-4e66-b4ac-4e71e1685743","language":"ja","slug":"野菜スープ","public_path":"/ja/野菜スープ","source_url":null,"title":"野菜スープ（じゃがいも・いんげん入り）","excerpt":"澄んだスープに、じゃがいも、にんじん、ズッキーニ、さやいんげん、トマトを入れた手作りの野菜スープ。ひとつの鍋で作れて、6人分です。","summary":"この野菜スープは、玉ねぎ、にんにく、にんじん、セロリのソフリットから始め、澄んだスープにじゃがいも、トマト、ズッキーニ、さやいんげんを入れて煮込みます。野菜は小さくやわらかく仕上がり、最後に生のパセリを加えます。\n\n下ごしらえ20分、加熱45分です。6人分です。","category":"スープ・ポタージュ","difficulty":"簡単","course":"スープ","cuisine":"インターナショナル","prep_time_minutes":20,"cook_time_minutes":45,"total_time_minutes":65,"servings":6,"keywords":["野菜スープ","野菜スープ レシピ","野菜スープ 作り方","手作り 野菜スープ","じゃがいも 野菜スープ","簡単 野菜スープ","澄んだ 野菜スープ"],"ingredients":[{"name":"玉ねぎ（大）","amount":"1","unit":"","group":"ソフリット用"},{"name":"にんにく","amount":"3","unit":"","group":"ソフリット用"},{"name":"にんじん","amount":"3","unit":"","group":"ソフリット用"},{"name":"セロリ（茎）","amount":"2","unit":"","group":"ソフリット用"},{"name":"オリーブオイル","amount":"2","unit":"大さじ","group":"ソフリット用"},{"name":"完熟トマト","amount":"3","unit":"","group":"スープ用"},{"name":"じゃがいも","amount":"2","unit":"","group":"スープ用"},{"name":"野菜スープ（ブイヨン）","amount":"2000","unit":"ml","group":"スープ用"},{"name":"ズッキーニ","amount":"1","unit":"","group":"スープ用"},{"name":"さやいんげん","amount":"200","unit":"g","group":"スープ用"},{"name":"塩","amount":"1","unit":"小さじ","group":"スープ用"},{"name":"黒こしょう","amount":"1/2","unit":"小さじ","group":"スープ用"},{"name":"パセリ（生）","amount":"15","unit":"g","group":"スープ用"}],"steps":[{"title":"材料を準備する","content":"野菜をよく洗い、玉ねぎ大1個、にんにく3片、にんじん3本、セロリ2本、じゃがいも2個、完熟トマト3個、ズッキーニ1本、さやいんげん200g、パセリ、野菜ブイヨン2リットル、オリーブオイル、塩、こしょうを用意します。","image_url":"/recetas/sopa-de-verduras/paso-01.webp","image_alt":"野菜スープ（じゃがいも・いんげん入り）: 材料を準備する"},{"title":"野菜を切る","content":"玉ねぎとにんにくはごく細かいみじん切りにします。にんじんとセロリは5mm角、じゃがいも、ズッキーニ、トマトは1cm角に切ります。さやいんげんは1cmの長さに切り、パセリはみじん切りにします。","image_url":"/recetas/sopa-de-verduras/paso-02.webp","image_alt":"野菜スープ（じゃがいも・いんげん入り）: 野菜を切る"},{"title":"ソフリットを作る","content":"大きめの鍋にオリーブオイル大さじ2を入れて中火で熱します。玉ねぎ、にんにく、にんじん、セロリをひとつまみの塩とともに加え、混ぜながら8分、玉ねぎが透き通るまで炒めます。","image_url":"/recetas/sopa-de-verduras/paso-03.webp","image_alt":"野菜スープ（じゃがいも・いんげん入り）: ソフリットを作る"},{"title":"トマト、じゃがいも、ブイヨンを加える","content":"トマトとじゃがいもを加えて2分混ぜ、温めたブイヨン2リットルを注ぎます。火を強めて沸騰させます。","image_url":"/recetas/sopa-de-verduras/paso-04.webp","image_alt":"野菜スープ（じゃがいも・いんげん入り）: トマト、じゃがいも、ブイヨンを加える"},{"title":"ふたをして煮る","content":"弱火にして、鍋に半分ふたをし、じゃがいもがほぼやわらかくなるまで15分煮ます。","image_url":"/recetas/sopa-de-verduras/paso-05.webp","image_alt":"野菜スープ（じゃがいも・いんげん入り）: ふたをして煮る"},{"title":"ズッキーニとさやいんげんを加える","content":"ズッキーニとさやいんげんを加えます。塩小さじ1の残りとこしょうを入れ、弱火で10分煮ます。","image_url":"/recetas/sopa-de-verduras/paso-06.webp","image_alt":"野菜スープ（じゃがいも・いんげん入り）: ズッキーニとさやいんげんを加える"},{"title":"混ぜて確かめる","content":"木べらで混ぜ、じゃがいもとさやいんげんを1つずつ刺してみます。形が残っていて、やわらかければ完成です。まだかたければ、さらに3〜5分煮ます。","image_url":"/recetas/sopa-de-verduras/paso-07.webp","image_alt":"野菜スープ（じゃがいも・いんげん入り）: 混ぜて確かめる"},{"title":"味をみて盛りつける","content":"スープの味をみて、塩とこしょうで調整します。火を止め、刻んだパセリを加えて、熱いうちに盛りつけます。","image_url":"/recetas/sopa-de-verduras/paso-08.webp","image_alt":"野菜スープ（じゃがいも・いんげん入り）: 味をみて盛りつける"}],"image_url":"/recetas/sopa-de-verduras/portada.webp","gallery":[{"url":"/recetas/sopa-de-verduras/portada.webp","alt":"野菜スープ（じゃがいも・いんげん入り）"}],"notes":"市販のブイヨンを使うときは、塩分が入っていることが多いので、塩を加える前に味をみてください。野菜は同じくらいの大きさに切ると、同時に火が通ります。ズッキーニとさやいんげんは、煮くずれしないように後から加えます。ズッキーニやさやいんげんは、グリーンピースやほうれん草など、季節の野菜に替えても作れます。スープは、ふたをして冷蔵庫で4日、冷凍で3か月保存できます。解凍後は、じゃがいもが少しやわらかくなります。","nutrition":{"calories":166,"protein_g":4.7,"carbs_g":28,"fat_g":5.4,"sodium_mg":643,"serving_size":"1人分（約400ml）","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"100gあたりの栄養素に材料の重量を掛け、6人分で割って合計しています。玉ねぎ150g、にんにく9g、にんじん240g、セロリ100g、オリーブオイル27g、トマト400g、じゃがいも400g、野菜ブイヨン2,000g（手作りまたは減塩ブイヨンの目安の値で近似、FDC番号なし）、ズッキーニ200g、さやいんげん200g、塩6g、こしょう1.2g、パセリ15gを使用しています。すべて全量を計算しています。","note":"1人分の目安です。ナトリウムは主にブイヨンと加える塩によって変わり、市販のブイヨンでは多くなることがあります。"},"seo":{"title":"野菜スープ（じゃがいも・いんげん入り）の作り方 | Manual de Cocina","description":"澄んだスープに、じゃがいも、にんじん、ズッキーニ、さやいんげん、トマトを入れた手作り野菜スープ。ひとつの鍋で6人分。作り方を写真付きで解説します。","image_variants":["/recetas/sopa-de-verduras/portada-1x1.webp","/recetas/sopa-de-verduras/portada-4x3.webp","/recetas/sopa-de-verduras/portada-16x9.webp"],"faq":[{"q":"野菜スープは何分煮ますか？","a":"全部で約45分です。ソフリットに8分、じゃがいもがほぼやわらかくなるまで15分、ズッキーニとさやいんげんを入れてさらに10分です。"},{"q":"野菜スープは冷凍できますか？","a":"はい、密閉容器で3か月まで冷凍できます。解凍後はじゃがいもが少しやわらかくなりますが、味は変わりません。"},{"q":"スープの野菜は何に替えられますか？","a":"ズッキーニやさやいんげんは、グリーンピース、ほうれん草、キャベツ、さつまいもに替えられます。かたい野菜を先に、やわらかい野菜を最後に加えます。"}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"f62ca51f-4aa5-54da-8040-4bf7d36f8ab3","recipe_group_id":"08fc2875-3e69-4e66-b4ac-4e71e1685743","language":"pt","slug":"sopa-de-legumes","public_path":"/pt/sopa-de-legumes","source_url":null,"title":"Sopa de legumes com batata e vagem","excerpt":"Sopa de legumes caseira com caldo claro, batata, cenoura, abobrinha, vagem e tomate. Feita em uma panela só, rende 6 porções.","summary":"Esta sopa de legumes começa com um refogado de cebola, alho, cenoura e salsão e cozinha em caldo claro com batata, tomate, abobrinha e vagem. Os legumes ficam em pedaços pequenos e macios, e a salsinha fresca entra no final.\n\nLeva 20 minutos de preparo e 45 de cozimento. Rende 6 porções.","category":"Sopas e cremes","difficulty":"Fácil","course":"Sopa","cuisine":"Internacional","prep_time_minutes":20,"cook_time_minutes":45,"total_time_minutes":65,"servings":6,"keywords":["sopa de legumes","receita de sopa de legumes","sopa de legumes caseira","como fazer sopa de legumes","sopa de legumes com batata","sopa de legumes fácil","sopa de legumes com caldo"],"ingredients":[{"name":"cebola grande","amount":"1","unit":"","group":"Para o refogado"},{"name":"dentes de alho","amount":"3","unit":"","group":"Para o refogado"},{"name":"cenouras","amount":"3","unit":"","group":"Para o refogado"},{"name":"talos de salsão","amount":"2","unit":"","group":"Para o refogado"},{"name":"azeite","amount":"2","unit":"colher de sopa","group":"Para o refogado"},{"name":"tomates maduros","amount":"3","unit":"","group":"Para a sopa"},{"name":"batatas","amount":"2","unit":"","group":"Para a sopa"},{"name":"caldo de legumes","amount":"2000","unit":"ml","group":"Para a sopa"},{"name":"abobrinha","amount":"1","unit":"","group":"Para a sopa"},{"name":"vagem","amount":"200","unit":"g","group":"Para a sopa"},{"name":"sal","amount":"1","unit":"colher de chá","group":"Para a sopa"},{"name":"pimenta-do-reino","amount":"1/2","unit":"colher de chá","group":"Para a sopa"},{"name":"salsinha fresca","amount":"15","unit":"g","group":"Para a sopa"}],"steps":[{"title":"Separe os ingredientes","content":"Lave bem os legumes e tenha à mão 1 cebola grande, 3 dentes de alho, 3 cenouras, 2 talos de salsão, 2 batatas, 3 tomates maduros, 1 abobrinha, 200 g de vagem, salsinha, 2 litros de caldo de legumes, azeite, sal e pimenta.","image_url":"/recetas/sopa-de-verduras/paso-01.webp","image_alt":"Sopa de legumes com batata e vagem: Separe os ingredientes"},{"title":"Corte os legumes","content":"Pique a cebola e o alho bem fininhos. Corte a cenoura e o salsão em cubos de ½ cm, e as batatas, a abobrinha e os tomates em cubos de 1 cm. Corte a vagem em pedaços de 1 cm e pique a salsinha.","image_url":"/recetas/sopa-de-verduras/paso-02.webp","image_alt":"Sopa de legumes com batata e vagem: Corte os legumes"},{"title":"Faça o refogado","content":"Aqueça 2 colheres de sopa de azeite em uma panela grande em fogo médio. Junte a cebola, o alho, a cenoura e o salsão com uma pitada de sal e cozinhe por 8 minutos, mexendo, até a cebola ficar transparente.","image_url":"/recetas/sopa-de-verduras/paso-03.webp","image_alt":"Sopa de legumes com batata e vagem: Faça o refogado"},{"title":"Junte tomate, batata e caldo","content":"Acrescente os tomates e as batatas, mexa por 2 minutos e despeje os 2 litros de caldo quente. Aumente o fogo até ferver.","image_url":"/recetas/sopa-de-verduras/paso-04.webp","image_alt":"Sopa de legumes com batata e vagem: Junte tomate, batata e caldo"},{"title":"Cozinhe tampada","content":"Baixe o fogo, tampe a panela parcialmente e cozinhe por 15 minutos, até as batatas ficarem quase macias.","image_url":"/recetas/sopa-de-verduras/paso-05.webp","image_alt":"Sopa de legumes com batata e vagem: Cozinhe tampada"},{"title":"Junte abobrinha e vagem","content":"Acrescente a abobrinha e a vagem. Adicione o restante da colher de chá de sal e a pimenta e cozinhe por 10 minutos em fogo baixo.","image_url":"/recetas/sopa-de-verduras/paso-06.webp","image_alt":"Sopa de legumes com batata e vagem: Junte abobrinha e vagem"},{"title":"Mexa e confira","content":"Mexa com uma colher de pau e espete uma batata e uma vagem: devem estar macias, mas inteiras. Se ainda estiverem firmes, cozinhe de 3 a 5 minutos a mais.","image_url":"/recetas/sopa-de-verduras/paso-07.webp","image_alt":"Sopa de legumes com batata e vagem: Mexa e confira"},{"title":"Prove e sirva","content":"Prove o caldo e ajuste o sal e a pimenta. Desligue o fogo, junte a salsinha picada e sirva a sopa bem quente.","image_url":"/recetas/sopa-de-verduras/paso-08.webp","image_alt":"Sopa de legumes com batata e vagem: Prove e sirva"}],"image_url":"/recetas/sopa-de-verduras/portada.webp","gallery":[{"url":"/recetas/sopa-de-verduras/portada.webp","alt":"Sopa de legumes com batata e vagem"}],"notes":"Se usar caldo pronto, prove antes de salgar, porque ele costuma já ter sal. Corte os legumes em tamanhos parecidos para cozinharem ao mesmo tempo. A abobrinha e a vagem entram depois para não desmancharem. Dá para trocar a abobrinha ou a vagem por outros legumes da estação, como ervilha ou espinafre. A sopa dura 4 dias na geladeira, bem tampada, e pode ser congelada por até 3 meses; as batatas ficam um pouco mais macias depois de descongelar.","nutrition":{"calories":166,"protein_g":4.7,"carbs_g":28,"fat_g":5.4,"sodium_mg":643,"serving_size":"1 porção (cerca de 400 ml)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Soma dos nutrientes por 100 g multiplicados pelo peso dos ingredientes e divididos por 6 porções: 150 g de cebola, 9 g de alho, 240 g de cenoura, 100 g de salsão, 27 g de azeite, 400 g de tomate, 400 g de batata, 2.000 g de caldo de legumes (aproximado com valores indicativos de caldo caseiro ou com pouco sódio, sem código FDC), 200 g de abobrinha, 200 g de vagem, 6 g de sal, 1,2 g de pimenta e 15 g de salsinha, tudo contado.","note":"Estimativa por porção. O sódio depende principalmente do caldo e do sal que você adicionar; com caldo pronto pode ser maior."},"seo":{"title":"Sopa de legumes com batata e vagem | Manual de Cocina","description":"Sopa de legumes caseira com caldo claro, batata, cenoura, abobrinha, vagem e tomate. Uma panela só, rende 6 porções. Passo a passo com fotos.","image_variants":["/recetas/sopa-de-verduras/portada-1x1.webp","/recetas/sopa-de-verduras/portada-4x3.webp","/recetas/sopa-de-verduras/portada-16x9.webp"],"faq":[{"q":"Quanto tempo leva para cozinhar a sopa de legumes?","a":"Cerca de 45 minutos no total: 8 para o refogado, 15 até as batatas ficarem quase macias e mais 10 com a abobrinha e a vagem."},{"q":"Dá para congelar a sopa de legumes?","a":"Sim, por até 3 meses em recipientes fechados. Depois de descongelar, as batatas ficam um pouco mais macias, mas o sabor se mantém."},{"q":"Quais legumes posso trocar na sopa?","a":"Você pode trocar a abobrinha ou a vagem por ervilha, espinafre, repolho ou batata-doce. Coloque primeiro os legumes mais firmes e, no final, os mais macios."}]},"published":true,"editorial_status":"published","content_html":""}
]$j$::jsonb;
  ts constant timestamptz := now();
  n int;
begin
  if (select count(*) from public.recipes where recipe_group_id = g) <> 1
     or not exists (select 1 from public.recipes where id = es_id and language = 'es' and published = false and public_path = '/sopa-de-verduras') then
    raise exception 'Estado previo inesperado del grupo';
  end if;
  if exists (select 1 from public.recipes where id <> es_id and (public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)
      or (language, slug) in (select x->>'language', x->>'slug' from jsonb_array_elements(j) x))) then
    raise exception 'Colisión de slug/public_path';
  end if;
  if exists (select 1 from public.content_pages where public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)) then
    raise exception 'Colisión con content_pages';
  end if;

  update public.recipes r set
    title = x.title, excerpt = x.excerpt, summary = x.summary, ingredients = x.ingredients, steps = x.steps,
    category = x.category, prep_time_minutes = x.prep_time_minutes, cook_time_minutes = x.cook_time_minutes,
    total_time_minutes = x.total_time_minutes, servings = x.servings, image_url = x.image_url,
    content_html = x.content_html, notes = x.notes, difficulty = x.difficulty, course = x.course,
    cuisine = x.cuisine, keywords = x.keywords, nutrition = x.nutrition, gallery = x.gallery, seo = x.seo,
    editorial_status = 'published', ready_at = ts, published = true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where r.id = es_id and x.language = 'es';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'UPDATE ES afectó % filas', n; end if;

  insert into public.recipes (id, recipe_group_id, language, slug, public_path, source_url, title, excerpt, summary,
    ingredients, steps, category, prep_time_minutes, cook_time_minutes, total_time_minutes, servings, image_url,
    content_html, notes, difficulty, course, cuisine, keywords, nutrition, gallery, seo, editorial_status, ready_at, published)
  select x.id, g, x.language, x.slug, x.public_path, null, x.title, x.excerpt, x.summary,
    x.ingredients, x.steps, x.category, x.prep_time_minutes, x.cook_time_minutes, x.total_time_minutes, x.servings, x.image_url,
    '', x.notes, x.difficulty, x.course, x.cuisine, x.keywords,
    x.nutrition || jsonb_build_object('inputs', (select nutrition->'inputs' from public.recipes where id = es_id)),
    x.gallery, x.seo, 'published', ts, true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where x.language <> 'es';
  get diagnostics n = row_count;
  if n <> 6 then raise exception 'INSERT afectó % filas', n; end if;

  if (select count(*) from public.recipes where recipe_group_id = g and published and editorial_status = 'published'
        and language in ('es','de','en','fr','it','ja','pt')) <> 7 then
    raise exception 'El grupo no quedó con 7 filas publicadas';
  end if;
end
$pub$;
